Say: "{% set task_name_final = task_name or input_vars.get("taskName") %}
{% if task_name_final == "CallerIdentification" %}
{% if function_responses and function_responses.get('get_contract_and_claims_data_ivr') %}
{%- set fn = function_responses.get('get_contract_and_claims_data_ivr') %}
{%- set resp = fn.response if (fn and fn.response is not none) else None %}
{% if resp and resp.success == true and resp.contractClaims.contract | length >0 %}
   Thanks for calling Assurant! I have your account information pulled up... how can I help you today?
{% else %}
   Thanks for calling Assurant! To best serve you, could you first tell me if you are a customer calling about your own contract, a dealer selling Assurant products, an independent professional repair facility, or an Assurant employee?
{% endif %}
{% else %}
   Thanks for calling Assurant! To best serve you, could you first tell me if you are a customer calling about your own contract, a dealer selling Assurant products, an independent professional repair facility, or an Assurant employee?
{% endif %}
{% elif task_name_final == "CarRentalInquiry" %}
{%- if function_responses and function_responses.get('get_contract_and_claims_data_V2') -%}
  {%- set fn = function_responses.get('get_contract_and_claims_data_V2') -%}
  {%- if fn.response and fn.response.escalation == true -%}
      I understand you have a question about your car rental benefits. How can I help?
  {%- elif fn.response -%}
    {%- set claim_details = fn.response.contractClaims.contract[0].claims -%}
    {%- set number_of_claims = claim_details | length -%}
    {%- set inactive_claim_status = ['Closed','Payment Approved','Paid','Denied'] -%}
    {%- set contract_make = fn.response.contractClaims.contract[0].make -%}
    {%- set contract_model = fn.response.contractClaims.contract[0].model -%}

    {%- if number_of_claims == 0 -%}
      Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. I don't see any claims for your vehicle right now. Would you like to know more about how to start a new claim, or do you have other questions about car rentals?
    {%- else -%}
      {%- set open_claims = [] -%}
      {%- for claim in claim_details -%}
        {%- if claim.status not in inactive_claim_status -%}
          {%- set _ = open_claims.append(claim) -%}
        {%- endif -%}
      {%- endfor -%}

      {%- if open_claims -%}
        {%- set open_claims = open_claims | sort(attribute='createdOn', reverse=True) -%}
        {%- set current_claim = open_claims[0] -%}
        {%- set claim_status = (current_claim.status or '') -%}

        {%- if claim_status == "Authorization Approved" -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. Your most recent claim is authorized. Rental options will be reviewed as part of your claim. Do you have questions about how to get your rental car, extend your rental or get reimbursed?
        {%- elif claim_status == "Correction Needed" -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. Your most recent claim was approved – but we are waiting for additional information from your repair facility to proceed with payment. In the meantime, do you have any other questions about your car rental?
        {%- elif claim_status == "Open" -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. Your most recent claim is currently open, but it still requires final authorization before the rental benefits can kick in. In the meantime, do you have other questions about car rentals or how the process works?
        {%- elif claim_status == "Draft" -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. Your most recent claim is in 'draft' status, which means that it still needs documentation from your repair facility. In the meantime, do you have other questions about car rental?
        {%- elif claim_status == "Manual Review" -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. Your most recent claim is currently being reviewed. We will typically make a decision within one or two business days. In the meantime, do you have other questions about car rentals?
        {%- elif claim_status == "Inspection Assigned" -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. For your most recent claim, an independent inspection company will need to visit your vehicle to take a look, which usually happens within two or three business days. In the meantime, do you have other questions about car rentals?
        {%- elif claim_status == "Inspection Requested" -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. For your most recent claim, an independent inspection company will need to visit your vehicle to take a look, which usually happens within two or three business days. In the meantime, do you have other questions about car rentals?
        {%- elif claim_status == "Sent Back for More Info" -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. Your most recent claim was sent back to the repair facility for more information. In the meantime, do you have other questions about car rentals?
        {%- else -%}
          Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. Your most recent claim hasn't been authorized yet. Rental benefits kick in only after the repair claim gets authorized. In the meantime, do you have other questions about car rentals?
        {%- endif -%}

      {%- else -%}
        Hello! I see you're calling about your {{ contract_make }} {{ contract_model }}. I don't see an active claim for your vehicle right now. What would you like to know about your car rental benefits?
      {%- endif -%}
    {%- endif -%}
  {%- endif -%}
{%- else -%}
  I understand you have a question about your car rental benefits. How can I help?
{%- endif -%}

{%- else -%}
Thanks for calling Assurant. How can I help you today?
{% endif %}"

